  const duck=dino.duck,box={x:dino.x+9,y:dino.y+(duck?29:12),w:duck?48:38,h:duck?22:47};for(let o of obstacles){let b=o.type==='cactus'?{x:o.x+1,y:ground-o.h+5,w:o.w*.45,h:o.h-5}:{x:o.x-17,y:o.y-8,w:35,h:28};if(box.x<b.x+b.w-5&&box.x+box.w>b.x+5&&box.y< b.y+b.h-3&&box.y+box.h>b.y+4){endGame();break}}
 }
 function jump(){if(mode==='ready'){start();return}if(mode!=='playing')return;if(dino.y>=ground-64){dino.vy=-13.6;beep(540,.1);for(let i=0;i<5;i++)particles.push({x:dino.x+24,y:ground-4,vx:(Math.random()-.5)*3,vy:-Math.random()*2,life:18,r:2+Math.random()*2,color:'#e6d49c'})}}
 function start(){mode='playing';score=0;speed=5.2;spawn=55;obstacles=[];particles=[];dino.y=ground-64;dino.vy=0;dino.duck=false;overlay.classList.add('hidden');statePill.classList.add('live');stateText.textContent='CORRIDA EM ANDAMENTO';scoreEl.textContent='00000'}
-function endGame(){mode='over';dino.duck=false;beep(170,.22);statePill.classList.remove('live');stateText.textContent='FIM DE JOGO';let final=Math.floor(score);if(final>best){best=final;localStorage.setItem('dino-best',best);bestEl.textContent=String(best).padStart(5,'0')}document.getElementById('dialogEmoji').textContent=final>=best&&final>0?'🏆':'🦴';document.getElementById('dialogTitle').textContent=final>=best&&final>0?'Novo recorde!':'Opa, bateu!';document.getElementById('dialogCopy').textContent=`Você correu ${final} metros pelo vale. Mais uma tentativa?`;document.getElementById('startBtn').innerHTML='Tentar de novo&nbsp; ↻';overlay.classList.remove('hidden')}
+function endGame(){mode='over';dino.duck=false;beep(170,.22);statePill.classList.remove('live');stateText.textContent='FIM DE JOGO';let final=Math.floor(score),isNew=final>best;if(isNew){best=final;localStorage.setItem('dino-best',best);bestEl.textContent=String(best).padStart(5,'0')}document.getElementById('dialogEmoji').textContent=isNew?'🏆':'🦴';document.getElementById('dialogTitle').textContent=isNew?'Novo recorde!':'Opa, bateu!';document.getElementById('dialogCopy').textContent=`Você correu ${final} metros pelo vale. Mais uma tentativa?`;document.getElementById('startBtn').innerHTML='Tentar de novo&nbsp; ↻';overlay.classList.remove('hidden')}
 document.getElementById('startBtn').addEventListener('click',start);document.getElementById('resetBtn').addEventListener('click',()=>{mode='ready';score=0;scoreEl.textContent='00000';obstacles=[];dino.y=ground-64;dino.vy=0;statePill.classList.remove('live');stateText.textContent='PRONTO PARA CORRER';document.getElementById('dialogEmoji').textContent='🌿';document.getElementById('dialogTitle').textContent='Uma aventura jurássica!';document.getElementById('dialogCopy').textContent='Ajude o Tito a atravessar o vale. Pule os cactos e cuidado com quem voa!';document.getElementById('startBtn').innerHTML='Começar a correr&nbsp; →';overlay.classList.remove('hidden')});
 document.getElementById('soundBtn').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫':'♩';e.currentTarget.style.background=soundOn?'#e7eddc':'';beep()});
 canvas.addEventListener('pointerdown',e=>{if(mode==='playing'){e.preventDefault();jump()}});
 window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','KeyW','KeyS'].includes(e.code))e.preventDefault();if(e.code==='Space'||e.code==='ArrowUp'||e.code==='KeyW')jump();if(e.code==='ArrowDown'||e.code==='KeyS'){if(mode==='playing')dino.duck=true}if(e.code==='Enter'&&mode!=='playing')start()});window.addEventListener('keyup',e=>{if(e.code==='ArrowDown'||e.code==='KeyS')dino.duck=false});
